import{lerp as q}from"../../math.js";export function lineChunk(o,l,w,b,n){const y=[];let u=w,s=0,c=l.slice(w,2);for(;s<o&&u+n<b;){const[t,e]=c.slice(-2),M=l[u+n],i=l[u+n+1],p=Math.sqrt((M-t)*(M-t)+(i-e)*(i-e));if(s+=p,s>=o){const h=(o-s+p)/p,m=q(t,M,h),x=q(e,i,h);c.push(m,x),y.push(c),c=[m,x],s==o&&(u+=n),s=0}else if(s<o)c.push(l[u+n],l[u+n+1]),u+=n;else{const h=p-s,m=q(t,M,h/p),x=q(e,i,h/p);c.push(m,x),y.push(c),c=[m,x],s=0,u+=n}}return s>0&&y.push(c),y}
